    public unsafe class Handle
    {
        private Attack attack;
        private Entity attacker, attacked;
        public void DecodeMe(out ushort SpellID, out ushort X, out ushort Y, out uint Target)
        {
            SpellID = X = Y = 0;
            Target = 0;
            if (attack.AttackType == Attack.Magic)
            {
                if (!attack.Decoded)
                {
                    #region GetSkillID
                    byte[] s = System.BitConverter.GetBytes(attack.EncodingSpellID);
                    SpellID = Convert.ToUInt16(((long)s[0] & 0xFF) | (((long)s[1] & 0xFF) << 8));
                    SpellID ^= (ushort)0x915d;
                    SpellID ^= (ushort)attack.Attacker;
                    SpellID = (ushort)(SpellID << 0x3 | SpellID >> 0xd);
                    SpellID -= 0xeb42;
                    #endregion

                    #region GetCoords
                    byte[] dx = System.BitConverter.GetBytes(attack.X);
                    X = (ushort)((dx[0] & 0xFF) | ((dx[1] & 0xFF) << 8));
                    X = (ushort)(X ^ (uint)(attack.Attacker & 0xffff) ^ 0x2ed6);
                    X = (ushort)(((X << 1) | ((X & 0x8000) >> 15)) & 0xffff);
                    X = (ushort)((X | 0xffff0000) - 0xffff22ee);

                    byte[] dy = System.BitConverter.GetBytes(attack.Y);
                    Y = (ushort)((dy[0] & 0xFF) | ((dy[1] & 0xFF) << 8));
                    Y = (ushort)(Y ^ (uint)(attack.Attacker & 0xffff) ^ 0xb99b);
                    Y = (ushort)(((Y << 5) | ((Y & 0xF800) >> 11)) & 0xffff);
                    Y = (ushort)((Y | 0xffff0000) - 0xffff8922);
                    #endregion

                    #region GetTarget
                    byte[] da = System.BitConverter.GetBytes(attack.Attacked);
                    Target = ((uint)da[0] & 0xFF) | (((uint)da[1] & 0xFF) << 8) | (((uint)da[2] & 0xFF) << 16) | (((uint)da[3] & 0xFF) << 24);
                    Target = ((((Target & 0xffffe000) >> 13) | ((Target & 0x1fff) << 19)) ^ 0x5F2D2463 ^ attack.Attacker) - 0x746F4AE6;
                    #endregion

                    attack.X = X;
                    attack.Y = Y;
                    attack.Damage = SpellID;
                    attack.Attacked = Target;
                    attack.Decoded = true;
                }
                else
                {
                    X = attack.X;
                    Y = attack.Y;
                    SpellID = (ushort)attack.Damage;
                    Target = attack.Attacked;
                }
            }
        }
        private sealed class InteractionOffer {
            internal Client.GameState Sender,Recipient;
            internal Entity SenderEntity,RecipientEntity;
            internal DateTime Until;
            internal uint Effect;
            internal bool HandHoldingRecorded;
            internal volatile bool Closed;
        }
        internal static Func<DateTime> InteractionClock=()=>DateTime.UtcNow;
        private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer> InteractionOffers=new System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer>();
        private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer> AcceptedInteractions=new System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer>();
        private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer> IssuedInteractions=new System.Runtime.CompilerServices.ConditionalWeakTable<Client.GameState,InteractionOffer>();
        internal static void InteractionDisconnected(Client.GameState owner) {
            if(owner==null)return;
            InteractionOffer offer;
            if(InteractionOffers.TryGetValue(owner,out offer))offer.Closed=true;
            if(IssuedInteractions.TryGetValue(owner,out offer))offer.Closed=true;
            if(AcceptedInteractions.TryGetValue(owner,out offer))offer.Closed=true;
            InteractionOffers.Remove(owner);IssuedInteractions.Remove(owner);AcceptedInteractions.Remove(owner);
        }
        private static void RefreshInteraction(Client.GameState owner,bool replaceSeparated=false) {
            InteractionOffer offer;bool clear=false;
            if(AcceptedInteractions.TryGetValue(owner,out offer))
                clear=offer.Closed || !Game.Features.QuestInventory.Player(offer.Sender) || !Game.Features.QuestInventory.Player(offer.Recipient)
                    || offer.Sender.DisconnectStarted || offer.Recipient.DisconnectStarted
                    || !ReferenceEquals(offer.Sender.Entity,offer.SenderEntity) || !ReferenceEquals(offer.Recipient.Entity,offer.RecipientEntity)
                    || offer.Sender.Map==null || !ReferenceEquals(offer.Sender.Map,offer.Recipient.Map)
                    || offer.Sender.Entity.MapID!=offer.Recipient.Entity.MapID
                    || replaceSeparated && (offer.Sender.Entity.X!=offer.Recipient.Entity.X || offer.Sender.Entity.Y!=offer.Recipient.Entity.Y);
            else if(InteractionOffers.TryGetValue(owner,out offer) || IssuedInteractions.TryGetValue(owner,out offer))
                clear=offer.Closed || InteractionClock()>=offer.Until || !Game.Features.QuestInventory.Player(offer.Sender)
                    || !Game.Features.QuestInventory.Player(offer.Recipient) || offer.Sender.DisconnectStarted || offer.Recipient.DisconnectStarted;
            if(!clear)return;
            InteractionDisconnected(owner);
            owner.Entity.InteractionWith=owner.Entity.InteractionType=0;
            owner.Entity.InteractionInProgress=owner.Entity.InteractionSet=false;
        }
        internal static bool HasAcceptedInteraction(Client.GameState a,Client.GameState b) {
            return a!=null && b!=null && !ReferenceEquals(a,b) && !a.DisconnectStarted && !b.DisconnectStarted
                && Game.Features.QuestInventory.Player(a) && Game.Features.QuestInventory.Player(b)
                && !a.Entity.Companion && !b.Entity.Companion && a.Map!=null && ReferenceEquals(a.Map,b.Map)
                && a.Entity.MapID==b.Entity.MapID && a.Entity.InteractionWith==b.Entity.UID && b.Entity.InteractionWith==a.Entity.UID
                && a.Entity.InteractionInProgress && b.Entity.InteractionInProgress
                && Kernel.GetDistance(a.Entity.X,a.Entity.Y,b.Entity.X,b.Entity.Y)<=20 && AcceptedPair(a,b);
        }
        // Effect is captured in the recipient-owned offer, never taken from a movement packet.
        private static bool HandHoldingPair(Client.GameState a,Client.GameState b) {
            InteractionOffer offer;
            return HasAcceptedInteraction(a,b) && AcceptedInteractions.TryGetValue(a,out offer) && offer.Effect==100004
                && OrdinaryInteractionBody(a.Entity.Body) && OrdinaryInteractionBody(b.Entity.Body)
                && EntityTable.IsGirl(a.Entity.Body)!=EntityTable.IsGirl(b.Entity.Body);
        }
        private static bool OrdinaryInteractionBody(ushort body) {
            return body==1003 || body==1004 || body==1005 || body==1006
                || body==2001 || body==2002 || body==2005 || body==2006;
        }
        internal static bool CanLeadHandHolding(Client.GameState leader) {
            Client.GameState peer;
            return leader!=null && leader.Entity!=null && Kernel.GamePool.TryGetValue(leader.Entity.InteractionWith,out peer)
                && HandHoldingPair(leader,peer);
        }
        private static void RecordHandHolding(Client.GameState a,Client.GameState b) {
            InteractionOffer offer;
            if(!HandHoldingPair(a,b) || !AcceptedInteractions.TryGetValue(a,out offer) || offer.HandHoldingRecorded)return;
            var first=a.Entity.UID<b.Entity.UID?a:b;var second=ReferenceEquals(first,a)?b:a;
            using(var c=DataHolder.MySqlConnection){c.Open();using(var t=c.BeginTransaction()){
                SkillTable.LockOwner(c,t,first);SkillTable.LockOwner(c,t,second);
                Game.Features.AppearanceState.AssertSaved(c,t,first);Game.Features.AppearanceState.AssertSaved(c,t,second);
                string key=first.Entity.UID.ToString(System.Globalization.CultureInfo.InvariantCulture)+":"
                    +second.Entity.UID.ToString(System.Globalization.CultureInfo.InvariantCulture);
                Game.Features.ProgressionEvidence.Complete(c,t,first.Entity.UID,10130,"hand-holding-v1",key,1);
                Game.Features.ProgressionEvidence.Complete(c,t,second.Entity.UID,10130,"hand-holding-v1",key,1);
                t.Commit();
            }}
            offer.HandHoldingRecorded=true;
            Game.Features.QuestInventory.Refresh(first);Game.Features.QuestInventory.Refresh(second);
        }
        internal static bool MoveInteractionFollower(Client.GameState leader,ushort oldX,ushort oldY,ushort x,ushort y,bool jump,uint movement,Action<Client.GameState> publish) {
            if(!Game.Features.QuestInventory.Player(leader) || publish==null)return false;
            bool moved=false;
            var request=new Attack(true){Attacked=leader.Entity.InteractionWith};
            WithInteractionPair(request,leader.Entity,delegate {
                var peer=Kernel.GamePool[request.Attacked];
                int range=jump?20:movement==GroundMovement.Slide?2:1;
                if(!HasAcceptedInteraction(leader,peer) || !leader.Entity.InteractionSet || !peer.Entity.InteractionSet
                    || (leader.Entity.Body!=1006 && leader.Entity.Body!=2005 && !HandHoldingPair(leader,peer))
                    || leader.Entity.X!=x || leader.Entity.Y!=y || peer.Entity.X!=oldX || peer.Entity.Y!=oldY
                    || (oldX==x && oldY==y) || Kernel.GetDistance(oldX,oldY,x,y)>range
                    || leader.Map.Floor==null || !leader.Map.Floor[x,y,MapObjectType.Player]
                    || (!jump && movement!=GroundMovement.Walk && movement!=GroundMovement.Run && movement!=GroundMovement.Slide)
                    || !Game.Features.SteedRaceCourse.CanMove(peer)
                    || Game.Features.ExorcismCombat.IsStunned(peer) || Game.Features.SnowBansheeCombat.IsStunned(peer)
                    || Game.Features.PurpleBansheeCombat.IsStunned(peer)
                    || ((jump || movement!=GroundMovement.Walk) && Game.Features.WarriorStance.BlockMovement(peer)))return;
                try {
                    peer.Entity.PX=oldX;peer.Entity.PY=oldY;
                    peer.Entity.Facing=Kernel.GetAngle(oldX,oldY,x,y);
                    peer.Entity.Action=jump?Enums.ConquerAction.Jump:Enums.ConquerAction.None;
                    peer.Entity.X=x;peer.Entity.Y=y;
                    Game.Features.TravelProgress.Arrived(peer,peer.Map,x,y,jump?Game.Features.TravelProgress.Arrival.Jump:Game.Features.TravelProgress.Arrival.Walk);
                    publish(peer);
                    if(!jump && (movement==GroundMovement.Walk || movement==GroundMovement.Run))RecordHandHolding(leader,peer);
                    moved=true;
                } catch(Exception ex) {
                    Game.Features.QuestInventory.Fail(peer,"paired-movement",ex);
                    Game.Features.QuestInventory.Fail(leader,"paired-movement",ex);
                }
            },true,null,20);
            return moved;
        }
        private static bool AcceptedPair(Client.GameState a,Client.GameState b) {
            InteractionOffer first,second;
            return AcceptedInteractions.TryGetValue(a,out first) && AcceptedInteractions.TryGetValue(b,out second)
                && ReferenceEquals(first,second) && !first.Closed && ReferenceEquals(first.Sender.Entity,first.SenderEntity)
                && ReferenceEquals(first.Recipient.Entity,first.RecipientEntity)
                && ((ReferenceEquals(first.Sender,a) && ReferenceEquals(first.Recipient,b))
                    || (ReferenceEquals(first.Sender,b) && ReferenceEquals(first.Recipient,a)));
        }
        private static void WithInteractionPair(Attack packet,Entity actor,Action work,bool paired=true,uint? target=null,int reach=18) {
            if(packet==null || actor==null || actor.Owner==null || actor.Companion)return;
            uint targetUid=target ?? packet.Attacked;
            var owner=actor.Owner;Client.GameState peer;
            if(!ReferenceEquals(owner.Entity,actor) || owner.DisconnectStarted || !Game.Features.QuestInventory.Player(owner)
                || !Kernel.GamePool.TryGetValue(targetUid,out peer) || ReferenceEquals(peer,owner)
                || !Game.Features.QuestInventory.Player(peer) || peer.DisconnectStarted || peer.Entity.Companion)return;
            var first=owner.Entity.UID<peer.Entity.UID?owner:peer;var second=ReferenceEquals(first,owner)?peer:owner;
            if(!Game.Features.SessionInstall.TryEnter(first.Entity.UID))return;
            try {
                if(!Game.Features.SessionInstall.TryEnter(second.Entity.UID))return;
                try {
                    if(!System.Threading.Monitor.TryEnter(first.ItemSyncRoot))return;
                    try {
                        if(!System.Threading.Monitor.TryEnter(second.ItemSyncRoot))return;
                        try {
                            Client.GameState actual;
                            RefreshInteraction(owner,!paired);RefreshInteraction(peer);
                            if(owner.DisconnectStarted || peer.DisconnectStarted || !Game.Features.QuestInventory.Player(owner) || !Game.Features.QuestInventory.Player(peer)
                                || !ReferenceEquals(owner.Entity,actor) || owner.Map==null || !ReferenceEquals(owner.Map,peer.Map)
                                || actor.MapID!=peer.Entity.MapID
                                || !Kernel.GamePool.TryGetValue(targetUid,out actual) || !ReferenceEquals(actual,peer)
                                || paired && (actor.InteractionWith!=peer.Entity.UID || peer.Entity.InteractionWith!=actor.UID)
                                || Kernel.GetDistance(actor.X,actor.Y,peer.Entity.X,peer.Entity.Y)>reach)return;
                            work();
                        } finally {System.Threading.Monitor.Exit(second.ItemSyncRoot);}
                    } finally {System.Threading.Monitor.Exit(first.ItemSyncRoot);}
                } finally {Game.Features.SessionInstall.Exit(second.Entity.UID);}
            } finally {Game.Features.SessionInstall.Exit(first.Entity.UID);}
        }
        #region Interations
        public class InteractionRequest
        {
            public InteractionRequest(Attack attack, Game.Entity a_client)
            {
                WithInteractionPair(attack,a_client,delegate {

                Client.GameState client = a_client.Owner;
                    var recipient=Kernel.GamePool[attack.Attacked];
                    if(client.Entity.InteractionInProgress || recipient.Entity.InteractionInProgress)return;
                    InteractionDisconnected(client);InteractionDisconnected(recipient);
                    client.Entity.InteractionSet=recipient.Entity.InteractionSet=false;
                    var invitation=new InteractionOffer{Sender=client,Recipient=recipient,
                        SenderEntity=client.Entity,RecipientEntity=recipient.Entity,Effect=attack.ResponseDamage,Until=InteractionClock().AddMinutes(2)};
                    InteractionOffers.Add(recipient,invitation);IssuedInteractions.Add(client,invitation);
                client.Entity.InteractionInProgress = false;
                client.Entity.InteractionWith = attack.Attacked;
                client.Entity.InteractionType = 0;
                client.InteractionEffect = attack.ResponseDamage;
                if (Kernel.GamePool.ContainsKey(attack.Attacked))
                {
                    Client.GameState clienttarget = Kernel.GamePool[attack.Attacked];
                    clienttarget.Entity.InteractionInProgress = false;
                    clienttarget.Entity.InteractionWith = client.Entity.UID;
                    clienttarget.Entity.InteractionType = 0;
                    clienttarget.InteractionEffect = attack.ResponseDamage;
                    attack.Attacker = client.Entity.UID;
                    attack.X = clienttarget.Entity.X;
                    attack.Y = clienttarget.Entity.Y;
                    attack.AttackType = 46;
                    clienttarget.Send(attack);
                    clienttarget.Send(attack);
                }

                },false);
            }
        }
        public class InteractionEffect
        {
            public InteractionEffect(Attack attack, Game.Entity a_client)
            {
                WithInteractionPair(attack,a_client,delegate {

                Client.GameState client = a_client.Owner;
                    var partner=Kernel.GamePool[client.Entity.InteractionWith];
                    if(!AcceptedPair(client,partner) || !client.Entity.InteractionInProgress || !partner.Entity.InteractionInProgress)return;
                if (Kernel.GamePool.ContainsKey(client.Entity.InteractionWith))
                {
                    Client.GameState clienttarget = Kernel.GamePool[client.Entity.InteractionWith];
                    if (clienttarget.Entity.X == client.Entity.X && clienttarget.Entity.Y == client.Entity.Y)
                    {
                        attack.Damage = client.Entity.InteractionType;
                        attack.ResponseDamage = client.InteractionEffect;
                        clienttarget.Entity.InteractionSet = true;
                        client.Entity.InteractionSet = true;
                        attack.Attacker = clienttarget.Entity.UID;
                        attack.Attacked = client.Entity.UID;
                        attack.AttackType = 47;
                        attack.X = clienttarget.Entity.X;
                        attack.Y = clienttarget.Entity.Y;
                        clienttarget.Send(attack);
                        attack.AttackType = 49;
                        attack.Attacker = client.Entity.UID;
                        attack.Attacked = clienttarget.Entity.UID;
                        client.SendScreen(attack, true);
                        attack.Attacker = clienttarget.Entity.UID;
                        attack.Attacked = client.Entity.UID;
                        client.SendScreen(attack, true);
                    }
                }

                },true,a_client==null?0u:a_client.InteractionWith);
            }
        }
        public class InteractionAccept
        {
            public InteractionAccept(Attack attack, Game.Entity a_client)
            {
                WithInteractionPair(attack,a_client,delegate {


                Client.GameState client = a_client.Owner;
                    var inviter=Kernel.GamePool[attack.Attacked];InteractionOffer offer;
                    if(!InteractionOffers.TryGetValue(client,out offer) || !ReferenceEquals(offer.Sender,inviter)
                        || !ReferenceEquals(offer.Recipient,client) || !ReferenceEquals(offer.SenderEntity,inviter.Entity)
                        || !ReferenceEquals(offer.RecipientEntity,client.Entity) || offer.Closed || InteractionClock()>=offer.Until
                        || client.Entity.InteractionInProgress || inviter.Entity.InteractionInProgress)return;
                    InteractionOffers.Remove(client);IssuedInteractions.Remove(inviter);
                    AcceptedInteractions.Remove(client);AcceptedInteractions.Remove(inviter);
                    AcceptedInteractions.Add(client,offer);AcceptedInteractions.Add(inviter,offer);
                if (client.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.Ride))
                    client.Entity.RemoveFlag((ulong)FlagsUpdate.Flags.Ride);
                if (client.Entity.InteractionWith != attack.Attacked) return;
                attack.ResponseDamage = client.InteractionEffect;
                client.Entity.InteractionSet = false;
                if (Kernel.GamePool.ContainsKey(attack.Attacked))
                {
                    Client.GameState clienttarget = Kernel.GamePool[attack.Attacked];
                    if (clienttarget.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.Ride))
                        clienttarget.Entity.RemoveFlag((ulong)FlagsUpdate.Flags.Ride);
                    clienttarget.Entity.InteractionSet = false;
                    if (clienttarget.Entity.InteractionWith != client.Entity.UID) return;
                    if (clienttarget.Entity.Body == 1003 || clienttarget.Entity.Body == 1004)
                    {
                        attack.Attacker = client.Entity.UID;
                        attack.X = client.Entity.X;
                        attack.Y = client.Entity.Y;
                        clienttarget.Send(attack);
                        clienttarget.Entity.InteractionInProgress = true;
                        client.Entity.InteractionInProgress = true;
                        clienttarget.Entity.InteractionType = attack.Damage;
                        clienttarget.Entity.InteractionX = client.Entity.X;
                        clienttarget.Entity.InteractionY = client.Entity.Y;
                        client.Entity.InteractionType = attack.Damage;
                        client.Entity.InteractionX = client.Entity.X;
                        client.Entity.InteractionY = client.Entity.Y;
                        if (clienttarget.Entity.X == client.Entity.X && clienttarget.Entity.Y == client.Entity.Y)
                        {
                            attack.Damage = client.Entity.InteractionType;
                            clienttarget.Entity.InteractionSet = true;
                            client.Entity.InteractionSet = true;
                            attack.Attacker = clienttarget.Entity.UID;
                            attack.Attacked = client.Entity.UID;
                            attack.AttackType = 47;
                            attack.X = clienttarget.Entity.X;
                            attack.Y = clienttarget.Entity.Y;
                            attack.ResponseDamage = clienttarget.InteractionEffect;
                            clienttarget.Send(attack);
                            attack.AttackType = 49;
                            attack.Attacker = client.Entity.UID;
                            attack.Attacked = clienttarget.Entity.UID;
                            client.SendScreen(attack, true);
                            attack.Attacker = clienttarget.Entity.UID;
                            attack.Attacked = client.Entity.UID;
                            client.SendScreen(attack, true);
                        }
                    }
                    else
                    {
                        attack.AttackType = 47;
                        attack.Attacker = client.Entity.UID;
                        attack.X = client.Entity.X;
                        attack.Y = client.Entity.Y;
                        clienttarget.Send(attack);
                        clienttarget.Entity.InteractionInProgress = true;
                        client.Entity.InteractionInProgress = true;
                        clienttarget.Entity.InteractionType = attack.Damage;
                        clienttarget.Entity.InteractionX = clienttarget.Entity.X;
                        clienttarget.Entity.InteractionY = clienttarget.Entity.Y;
                        client.Entity.InteractionType = attack.Damage;
                        client.Entity.InteractionX = clienttarget.Entity.X;
                        client.Entity.InteractionY = clienttarget.Entity.Y;
                        if (clienttarget.Entity.X == client.Entity.X && clienttarget.Entity.Y == client.Entity.Y)
                        {
                            clienttarget.Entity.InteractionSet = true;
                            client.Entity.InteractionSet = true;
                            attack.Attacker = clienttarget.Entity.UID;
                            attack.Attacked = client.Entity.UID;
                            attack.X = clienttarget.Entity.X;
                            attack.Y = clienttarget.Entity.Y;
                            attack.ResponseDamage = clienttarget.InteractionEffect;
                            clienttarget.Send(attack);
                            attack.AttackType = 49;
                            client.SendScreen(attack, true);
                            attack.Attacker = client.Entity.UID;
                            attack.Attacked = clienttarget.Entity.UID;
                            client.SendScreen(attack, true);
                        }
                    }
                }

                });
            }
        }
        public class InteractionStopEffect
        {
            public InteractionStopEffect(Attack attack, Game.Entity a_client)
            {
                WithInteractionPair(attack,a_client,delegate {

                Client.GameState client = a_client.Owner;
                    var partner=Kernel.GamePool[attack.Attacked];
                    InteractionDisconnected(client);InteractionDisconnected(partner);
                if (Kernel.GamePool.ContainsKey(attack.Attacked))
                {
                    Client.GameState clienttarget = Kernel.GamePool[attack.Attacked];
                    attack.Attacker = client.Entity.UID;
                    attack.Attacked = clienttarget.Entity.UID;
                    attack.Damage = client.Entity.InteractionType;
                    attack.X = client.Entity.X;
                    attack.Y = client.Entity.Y;
                    attack.AttackType = 50;
                    client.SendScreen(attack, true);
                    attack.Attacker = clienttarget.Entity.UID;
                    attack.Attacked = client.Entity.UID;
                    clienttarget.SendScreen(attack, true);
                    client.Entity.Teleport(client.Entity.MapID, client.Entity.X, client.Entity.Y);
