        #region TwilightDance
        internal static Func<Time32> TwilightClock = () => Time32.Now;
        private void TwilightAction(Entity attacker, SpellUse suse, SpellInformation spell, ushort X, ushort Y)
        {
            var pulse = CreateTwilightPulse(attacker, spell, X, Y);
            if (pulse != null) Server.Thread.DelayedTask.StartDelayedTask(() => pulse(), 0, 2, 400);
        }
        // Each cast owns its path and pulse counter; it never reuses Handle's mutable target/packet.
        internal static Action CreateTwilightPulse(Entity attacker, SpellInformation spell, ushort x, ushort y)
        {
            var owner = attacker == null ? null : attacker.Owner;
            if (owner == null || owner.ItemSyncRoot == null || spell == null || spell.ID != 12070
                || !ReferenceEquals(owner.Entity, attacker) || !Features.QuestInventory.Player(owner)
                || !owner.Spells.ContainsKey(spell.ID) || owner.Map == null) return null;
            var map = owner.Map;
            var mapVersion = attacker.MapTransitionVersion;
            var group = owner.ChampionGroup;
            var opponent = group == null ? null : ReferenceEquals(group.Player1, owner) ? group.Player2 : group.Player1;
            var opponentBody = opponent == null ? null : opponent.Entity;
            var path = new InLineAlgorithm(attacker.X, x, attacker.Y, y, (byte)spell.Distance).lcoords.ToArray();
            if (path.Length == 0) return null;
            var pulseGate = new object();
            int pulses = 0;
            bool closed = false;
            Time32 lastPulse = TwilightClock();
            return () => {
                lock (pulseGate) {
                    if (closed || pulses >= 3) return;
                    using (var champion = Champion.QualifierList.QualifierGroup.CombatLease.Acquire(attacker, opponentBody)) {
                        if (champion != null && !champion.Allowed) { closed = true; return; }
                        if (!Features.SessionInstall.TryEnter(attacker.UID)) return;
                        try {
                            if (!System.Threading.Monitor.TryEnter(owner.ItemSyncRoot)) return;
                            try {
                                Map liveMap;
                                if (!Features.QuestInventory.Player(owner) || owner.ShutdownStarted || owner.DisconnectStarted
                                    || !ReferenceEquals(owner.Entity, attacker) || attacker.Dead
                                    || !ReferenceEquals(owner.Map, map) || attacker.MapID != map.ID
                                    || attacker.MapTransitionVersion != mapVersion
                                    || !Kernel.Maps.TryGetValue(map.ID, out liveMap) || !ReferenceEquals(liveMap, map)
                                    || !ReferenceEquals(owner.ChampionGroup, group) || !owner.Spells.ContainsKey(spell.ID)) {
                                    closed = true; return;
                                }
                                var now = TwilightClock();
                                if (pulses != 0 && unchecked((uint)(now.Value - lastPulse.Value)) < 400) return;
                                lastPulse = now;
                                int i = ++pulses;
                                int selected = Math.Min(path.Length - 1, i * (path.Length / 3));
                                ushort px = (ushort)path[selected].X, py = (ushort)path[selected].Y;
                                if (px >= map.Floor.Bounds.Width || py >= map.Floor.Bounds.Height) { closed = true; return; }
                                var floor = new FloorItem(true) {
                                    UID = FloorItem.FloorUID.Next, MapObjType = MapObjectType.Item,
                                    ItemID = FloorItem.TwilightDance, ItemColor = (Enums.Color)(i + 1),
                                    MapID = map.ID, Type = FloorItem.Effect, X = px, Y = py,
                                    OnFloor = Time32.Now, Owner = owner, OwnerUID = attacker.UID
                                };
                                while (map.FloorItems.ContainsKey(floor.UID)) floor.UID = FloorItem.FloorUID.Next;
                                map.AddFloorItem(floor);
                                owner.SendScreenSpawn(floor, true);
                                owner.SendScreen(new Data(true) { UID = attacker.UID, Xt1 = px, Yt1 = py,
                                    ID = Data.RemoveTrap, wParam1 = attacker.X, wParam2 = attacker.Y }, true);
                                var use = new SpellUse(true) { Attacker = attacker.UID, Attacker1 = attacker.UID,
                                    SpellID = spell.ID, SpellLevel = spell.Level, X = px, Y = py };
                                foreach (var obj in owner.Screen.Objects) {
                                    if (obj == null || Kernel.GetDistance(obj.X, obj.Y, px, py) > spell.Range) continue;
                                    var packet = new Attack(true) { Attacker = attacker.UID, Attacked = obj.UID,
                                        AttackType = Attack.Magic, Damage = spell.ID, Decoded = true, X = px, Y = py };
                                    var target = obj as Entity;
                                    if (target != null && (target.EntityFlag == EntityFlag.Player || target.EntityFlag == EntityFlag.Monster)) {
                                        if (target.MapID != map.ID) continue;
                                        using (var health = Features.HealthMutationLease.Acquire(attacker, target)) {
                                            if (!health.Allowed || !CanAttack(attacker, target, spell, false)) continue;
                                            uint damage = Calculate.Melee(attacker, target, spell, ref packet);
                                            damage = (uint)(damage * (target.EntityFlag == EntityFlag.Player ? 2.2 : 1.5));
                                            ReceiveAttack(attacker, target, packet, ref damage, spell);
                                            use.AddTarget(target.UID, damage, packet);
                                        }
                                    } else if (obj.MapObjType == MapObjectType.SobNpc) {
                                        var targetNpc = obj as SobNpcSpawn;
                                        if (targetNpc == null || targetNpc.MapID != map.ID || !CanAttack(attacker, targetNpc, spell)) continue;
                                        uint damage = Calculate.Melee(attacker, targetNpc, ref packet);
                                        ReceiveAttack(attacker, targetNpc, packet, damage, spell);
                                        use.AddTarget(targetNpc.UID, damage, packet);
                                    }
                                }
                                if (use.Targets.Count > 0) owner.SendScreen(use, true);
                            } finally { System.Threading.Monitor.Exit(owner.ItemSyncRoot); }
                        } finally { Features.SessionInstall.Exit(attacker.UID); }
                    }
                }
            };
        }
