        public static void InfroEcho(FloorItem item, int count = 0)
        {
            var owner=item==null?null:item.Owner;if(owner==null || owner.ItemSyncRoot==null)return;
            lock(owner.ItemSyncRoot)lock(item){
                FloorItem current;var map=owner.Map;
                if(!Features.QuestInventory.Player(owner) || owner.Entity.Class/10!=6 || !owner.Spells.ContainsKey(12550)
                    || !Features.RebirthSkillRules.MonkEffect(item) || item.Type!=FloorItem.Effect || item.OwnerUID!=owner.Entity.UID
                    || map==null || map.ID!=item.MapID || owner.Entity.MapID!=item.MapID
                    || !map.FloorItems.TryGetValue(item.UID,out current) || !ReferenceEquals(item,current)
                    || item.X>=map.Floor.Bounds.Width || item.Y>=map.Floor.Bounds.Height)return;
                // The existing screen path removes the pillar after its pulse. Claim it once under its owner lock.
                item.Type=FloorItem.RemoveEffect;InfroEchoOwned(item,count);
            }
        }
        private static void InfroEchoOwned(FloorItem item, int count)

        {
            var client = item.Owner;
            var X = item.X;
            var Y = item.Y;
            if (!client.Spells.ContainsKey(12550))
                return;
            var spell = SpellTable.GetSpell(client.Spells[12550].ID, client.Spells[12550].Level);

            var attack = new Attack(true);
            attack.Attacker = client.Entity.UID;
            attack.X = X;
            attack.Y = Y;
            attack.Damage = spell.ID;
            attack.AttackType = Attack.Magic;
            SpellUse suse = new SpellUse(true);
            suse.Attacker = client.Entity.UID;
            suse.SpellID = spell.ID;
            suse.SpellLevel = spell.Level;
            suse.X = X;
            suse.Y = Y;
            suse.SpellEffect = 1;
            for (int c = 0; c < client.Screen.Objects.Length; c++)
            {
                if (c >= client.Screen.Objects.Length)
                    break;
                Interfaces.IMapObject _obj = client.Screen.Objects[c];
                if (_obj == null)
                    continue;
                if (_obj.MapObjType == MapObjectType.Monster)
                {
                    var attacked = _obj as Entity;
                    if (Kernel.GetDistance(X, Y, attacked.X, attacked.Y) <= spell.Range)
                    {
                        if (CanAttack(client.Entity, attacked, spell, attack.AttackType == Attack.Ranged))
                        {
                            uint damage = Game.Attacking.Calculate.Rango(client.Entity, attacked, ref attack);
                            damage = (uint)(damage * 3.8);

                            suse.Effect = attack.Effect;
                            ReceiveAttack(client.Entity, attacked, attack, ref damage, spell);
                            attacked.Stunned = true;
                            attacked.StunStamp = Time32.Now;
                            suse.AddTarget(attacked.UID, damage, attack);

                        }
                    }
                }
                if (_obj.MapObjType == MapObjectType.Player)
                {
                    var attacked = _obj as Entity;
                    var attacker = client.Entity;
                    if (Kernel.GetDistance(X, Y, attacked.X, attacked.Y) <= spell.Range)
                    {
                        if (CanAttack(client.Entity, attacked, spell, attack.AttackType == Attack.Ranged))
                        {


                            uint damage = Game.Attacking.Calculate.Rango(attacker, attacked, spell, ref attack);
                            damage = (uint)(damage * 2.8);
                            suse.Effect = attack.Effect;
                            ReceiveAttack(client.Entity, attacked, attack, ref damage, spell);
                            attacked.Stunned = true;
                            attacked.StunStamp = Time32.Now;
                            suse.AddTarget(attacked.UID, damage, attack);

                        }
                    }
                }
            }
            client.Entity.AttackPacket = null;
            client.SendScreen(suse, true);
        }
