        #region Pirate
        public static void TideTrap(FloorItem item, int count = 0)
        {
            var owner = item == null ? null : item.Owner;
            if (owner == null || owner.Entity == null || owner.ItemSyncRoot == null) return;
            lock (owner.ItemSyncRoot) lock (item) {
                FloorItem current; Map map;
                if (item.ItemID != FloorItem.TideTrap || item.Type != FloorItem.Effect || item.OwnerUID != owner.Entity.UID
                    || !Kernel.Maps.TryGetValue(item.MapID, out map)
                    || !map.FloorItems.TryGetValue(item.UID, out current) || !ReferenceEquals(item, current)) return;
                bool active = Features.QuestInventory.Player(owner) && !owner.ShutdownStarted && !owner.DisconnectStarted && owner.ChampionGroup == null
                    && ReferenceEquals(map, owner.Map) && owner.Entity.MapID == item.MapID
                    && item.X < map.Floor.Bounds.Width && item.Y < map.Floor.Bounds.Height
                    && item.X2 < map.Floor.Bounds.Width && item.Y2 < map.Floor.Bounds.Height;
                item.Type = FloorItem.RemoveEffect;
                try { if (active) TideTrapOwned(item, count); }
                finally { map.RemoveFloorItem(item); owner.RemoveScreenSpawn(item, true); }
            }
        }
        private static void TideTrapOwned(FloorItem item, int count)
        {
            var client = item.Owner;
            var X = item.X;
            var Y = item.Y;

            if (!client.Spells.ContainsKey(14250)) return;
            var spell = SpellTable.GetSpell(client.Spells[14250].ID, client.Spells[14250].Level);

            var spelluse = new SpellUse(true);
            spelluse.Attacker = client.Entity.UID;
            spelluse.SpellID = 14250;
            spelluse.SpellLevel = client.Spells[14250].Level;
            spelluse.SpellEffect = 1;
            spelluse.X = X;
            spelluse.Y = Y;
            var attack = new Attack(true);
            attack.Attacker = client.Entity.UID;
            attack.AttackType = Attack.Magic;
            attack.SpellID = 1;
            NewInLineAlgorithm Line = new NewInLineAlgorithm(item.X2, item.X, item.Y2, item.Y, client.Map, 9, spell.ID);
            #region Damage Area
            foreach (IMapObject _obj in client.Screen.Objects)
            {
                if (_obj.MapObjType == MapObjectType.Player)
                {
                    var attacked = _obj as Entity;
                    if (Kernel.GetDistance(item.X, item.Y, attacked.X, attacked.Y) < 9)
                    {
                        if (Line.InLine(attacked.X, attacked.Y, 3))
                        {
                            if (CanAttack(client.Entity, attacked, spell, attack.AttackType == Attack.Melee))
                            {
                                uint damage = item.TideTrapOnPlayer;
                                ReceiveAttack(client.Entity, attacked, attack, ref damage, spell);
                                spelluse.AddTarget(attacked.UID, damage, attack);
                            }
                        }
                    }
                }
                if (_obj.MapObjType == MapObjectType.Monster)
                {
                    var attacked = _obj as Entity;
                    if (Kernel.GetDistance(item.X, item.Y, attacked.X, attacked.Y) < 9)
                    {
                        if (Line.InLine(attacked.X, attacked.Y, 3))
                        {
                            if (CanAttack(client.Entity, attacked, spell, attack.AttackType == Attack.Melee))
                            {
                                uint damage = item.TideTrapOnMonster;
                                ReceiveAttack(client.Entity, attacked, attack, ref damage, spell);
                                spelluse.AddTarget(attacked.UID, damage, attack);
                            }
                        }
                    }
                }
            }
            #endregion
            client.Entity.AttackPacket = null;
            client.SendScreen(spelluse, true);
        }
