        private static void SeaBurialOwned(FloorItem item, int count)
        {
            var client = item.Owner;
            var X = item.X;
            var Y = item.Y;
            if (!client.Spells.ContainsKey((ushort)Enums.Skill.SeaBurial)) return;
            var spell = SpellTable.GetSpell(client.Spells[(ushort)Enums.Skill.SeaBurial].ID, client.Spells[(ushort)Enums.Skill.SeaBurial].Level);
            var spelluse = new SpellUse(true);
            spelluse.Attacker = client.Entity.UID;
            spelluse.SpellID = (ushort)Enums.Skill.SeaBurial;
            spelluse.SpellLevel = client.Spells[(ushort)Enums.Skill.SeaBurial].Level;
            spelluse.SpellEffect = 1;
            spelluse.X = X;
            spelluse.Y = Y;
            var attack = new Attack(true);
            attack.Attacker = client.Entity.UID;
            attack.AttackType = Attack.Magic;
            attack.SpellID = 1;
            if (!client.Entity.Dead)
            {
                NewInLineAlgorithm Line = new NewInLineAlgorithm(item.X, item.X2, item.Y, item.Y2, client.Map, (byte)spell.Distance, spell.ID);
                #region Damage Area
                foreach (IMapObject _obj in client.Screen.Objects)
                {
                    if (_obj.MapObjType == MapObjectType.Monster || _obj.MapObjType == MapObjectType.Player)
                    {
                        var attacked = _obj as Entity;
                        if (Kernel.GetDistance(item.X, item.Y, attacked.X, attacked.Y) < spell.Distance)
                        {
                            if (Line.InLine(attacked.X, attacked.Y, 1))
                            {
                                if (CanAttack(client.Entity, attacked, spell, attack.AttackType == Attack.Melee))
                                {
                                    uint damage = Calculate.Melee(client.Entity,attacked,spell,ref attack);
                                    ReceiveAttack(client.Entity, attacked, attack, ref damage, spell);
                                    spelluse.AddTarget(attacked.UID, damage, attack);
                                }
                            }
                        }
                    }
                    else if (_obj.MapObjType == MapObjectType.SobNpc)
                    {
                        var attackedsob = _obj as SobNpcSpawn;
                        if (Kernel.GetDistance(item.X, item.Y, attackedsob.X, attackedsob.Y) < spell.Distance)
                        {
                            if (Line.InLine(attackedsob.X, attackedsob.Y, 1))
                            {
                                if (CanAttack(client.Entity, attackedsob, spell))
                                {
                                    uint damage = Calculate.Melee(client.Entity, attackedsob,ref attack);
                                    ReceiveAttack(client.Entity, attackedsob, attack, damage, spell);
                                    spelluse.AddTarget(attackedsob.UID, damage, attack);
                                }
                            }
                        }
                    }
                }
                #endregion
            }
            client.Entity.AttackPacket = null;
            client.SendScreen(spelluse, true);
        }
