        // Cached screen membership is not authority to damage a player.
        private static bool LegacyMonsterAreaTarget(Entity attacker, Entity primary, Entity candidate)
        {
            if (candidate == null || candidate.EntityFlag != EntityFlag.Player
                || ReferenceEquals(candidate, primary) || candidate.Dead || candidate.MapID != attacker.MapID)
                return false;
            var owner = candidate.Owner;
            return owner != null && ReferenceEquals(owner.Entity, candidate)
                && (owner.Fake || (owner.Attackable && Revora.Game.Features.QuestInventory.Player(owner)));
        }
        private void Execute()
        {
            if (Revora.Game.Features.WaveDefenseSystem.BlocksPostAttack(attacker, attacked)) return;
            if (attacker != null && attacker.Owner != null && ReferenceEquals(attacker.Owner.Entity, attacker) && (Revora.Game.Features.ExorcismCombat.IsStunned(attacker.Owner) || Revora.Game.Features.SnowBansheeCombat.IsStunned(attacker.Owner) || Revora.Game.Features.PurpleBansheeCombat.IsStunned(attacker.Owner))) return;
            if (Revora.Game.Features.ExorcismCombat.Execute(attacker, attacked)) return;
            if (Revora.Game.Features.WarriorEpicCombat.IsEncounter(attacker) &&
                (attacker.MonsterInfo.ID == Revora.Game.Features.WarriorEpicCombat.SteleFamily || Revora.Game.Features.WarriorEpicCombat.BlockAttack(attacker, attacked))) return;
            if (Revora.Game.Features.TrojanEpicCombat.IsEncounter(attacker) && Revora.Game.Features.TrojanEpicCombat.BlockAttack(attacker, attacked)) return;
            if (Revora.Game.Features.SwordMasterCombat.Execute(attacker, attacked)) return;
            if (Revora.Game.Features.PurpleBansheeCombat.Execute(attacker, attacked)) return;
            if (Revora.Game.Features.SnowBansheeCombat.Execute(attacker, attacked)) return;
            if (Revora.Game.Features.TeratoCombat.Execute(attacker, attacked)) return;
            #region interactions
            if (attack != null)
            {
                switch (attack.AttackType)
                {
                    case Attack.InteractionRequest:
                        {
                            new InteractionRequest(attack, attacker); return;
                        }
                    case Attack.InteractionEffect:
                        {
                            new InteractionEffect(attack, attacker); return;
                        }
                    case Attack.InteractionAccept:
                        {
                            new InteractionAccept(attack, attacker); return;
                        }
                    case Attack.InteractionRefuse:
                        {
                            new InteractionRefuse(attack, attacker); return;
                        }
                    case Attack.InteractionStopEffect:
                        {
                            new InteractionStopEffect(attack, attacker); return;
                        }
                }
            }
            #endregion
            if (attacked != null && attacked.EntityFlag == EntityFlag.Player && attacked.Owner != null && !attacked.Owner.Fake)
                Revora.Game.Features.ExpeditionEvent.NotifyAction(attacked.Owner, "you were hit");
            #region Monster -> Player \ Monster
            if (attack == null)
            {
                if (attacker.EntityFlag != EntityFlag.Monster) return;
                if (attacker.Companion)
                {
                    if (Constants.PKForbiddenMaps.Contains(attacker.MapID)) return;
                }
                if (attacked.EntityFlag == EntityFlag.Player)
                {
                    if (attacked.Owner == null) return;
                    if (attacked.Owner.Fake)
                    {
                        HitWorldActor(attacker, attacked);
                        return;
                    }
                    if (!attacked.Owner.Attackable) return;
                    if (attacked.Dead)
                        if (attacked.Dead)
                        {
                            attacked.Die(attacker);
                            return;
                        }
                    bool scriptedMonsterHit = false;
                    #region Ice Queen
                    if (!scriptedMonsterHit && (attacker.Name == "IceQueen" || attacker.Name == "SnowBansheeSoul" || attacker.Name == "PurpleBanshee"))
                    {

                        uint rand = (uint)Revora.Kernel.Random.Next(1, 8);
                        switch (rand)
                        {
                            case 1:
                                attacker.MonsterInfo.SpellID = 10001;
                                break;
                            case 2:
                                attacker.MonsterInfo.SpellID = 10001;
                                break;
                            case 4:
                                attacker.MonsterInfo.SpellID = 10001;
                                break;
                            case 6:
                                attacker.MonsterInfo.SpellID = 10001;
                                break;
                        }
                        #region IceThrom AngerCop
                        if (attacker.MonsterInfo.SpellID == 30010 || attacker.MonsterInfo.SpellID == 10001)
                        {
                            uint damage = 0;
                            damage += (uint)Kernel.Random.Next(1000, 2000);
                            scriptedMonsterHit = true;
                            Revora.Game.Features.WarriorModes.MonsterCounter(attacker, attacked, damage);
                            if (attacked.Hitpoints <= damage)
                            {
                                attacked.Die(attacker);
                            }
                            else
                            {
                                attacked.Hitpoints -= damage;
                            }
                            if (attacker.Companion)
                                attacker.Owner.IncreaseExperience(Math.Min(damage, attacked.Hitpoints), true);
                            SpellUse suse = new SpellUse(true);
                            suse.Attacker = attacker.UID;
                            suse.SpellID = attacker.MonsterInfo.SpellID;
                            suse.X = attacked.X;
                            suse.Y = attacked.Y;
                            suse.AddTarget(attacked.UID, damage, attack);
                            attacked.Owner.SendScreen(suse, true);
                        }
                        #endregion
                        #region Chill
                        if (attacker.MonsterInfo.SpellID == 30011)
                        {
                            SpellUse suse = new SpellUse(true);
                            attack = new Attack(true);
                            attack.Effect = Attack.AttackEffects.None;
                            uint damage = 0;
                            damage += (uint)Kernel.Random.Next(1000, 2000);
