                    #region Checks
                    if (attack.Attacker != attacker.UID) return;
                    if (attacker.EntityFlag != EntityFlag.Player) return;
                    attacker.RemoveFlag((ulong)FlagsUpdate.Flags.Invisibility);
                    bool pass = false;
                    if (attack.AttackType == Attack.Melee)
                    {
                        if (attacker.OnFatalStrike())
                        {
                            if (attack.Attacked < 600000)
                            {
                                pass = true;
                            }
                        }
                    }
                    ushort decrease = 0;
                    if (attacker.OnCyclone())
                        decrease = 1;
                    if (attacker.OnSuperman())
                        decrease = 300;
                    if (!pass && attack.AttackType != Attack.Magic)
                    {
                        int milliSeconds = 500;
                        if (milliSeconds < 0 || milliSeconds > 5000)
                            milliSeconds = 0;
                        if (milliSeconds > 0)
                            if (attacker.ContainsFlag((ulong)FlagsUpdate.Flags.Infinity))
                                if (milliSeconds >= 300)
                                    milliSeconds -= 300;
                                else
