        public static bool isArcherSkill(uint ID)
        {
            if (ID >= 8000 && ID <= 9875)
                return true;
            return false;
        }
        public Handle(Attack attack, Entity attacker, Entity attacked)
        {
            this.attack = attack;
            this.attacker = attacker;
            this.attacked = attacked;
            using (var health = Revora.Game.Features.HealthMutationLease.Acquire(attacker, attacked))
            using (Revora.Game.Features.HeartEncounter.DamageLease(attacker, attacked))
            using (Revora.Game.Features.PlanetEncounter.DamageLease(attacker, attacked))
            {
                if (!health.Allowed) return;
                if (attack == null && Revora.Game.Features.HeartEncounter.BlockDamage(attacker, attacked)) return;
                if (attack == null && Revora.Game.Features.PlanetEncounter.BlockDamage(attacker, attacked)) return;
                using (Revora.Game.Features.XpCastAttribution.Begin(attacker))
                    this.Execute();
            }
        }
        public static void HandleAuraMonk(Game.Entity attacker, SpellInformation spell)
        {
            if(attacker==null || spell==null || attacker.Owner==null || attacker.Owner.ItemSyncRoot==null)return;
            lock(attacker.Owner.ItemSyncRoot)
            {
            if(!Revora.Game.Features.ArenaActors.Player(attacker.Owner) || !ReferenceEquals(attacker.Owner.Entity,attacker))return;
            ISkill learned;
            if(!attacker.Owner.Spells.TryGetValue(spell.ID,out learned))return;
            spell=SpellTable.GetSpell(spell.ID,learned.Level);if(spell==null)return;
            ulong statusFlag = 0;
            switch (spell.ID)
            {
                case 10424: statusFlag = (ulong)FlagsUpdate.Flags.EarthAura; break;
                case 10423: statusFlag = (ulong)FlagsUpdate.Flags.FireAura; break;
                case 10422: statusFlag = (ulong)FlagsUpdate.Flags.WaterAura; break;
                case 10421: statusFlag = (ulong)FlagsUpdate.Flags.WoodAura; break;
                case 10420: statusFlag = (ulong)FlagsUpdate.Flags.MetalAura; break;
                case 10410: statusFlag = (ulong)FlagsUpdate.Flags.FendAura; break;
                case 10395: statusFlag = (ulong)FlagsUpdate.Flags.TyrantAura; break;
            }

            if(statusFlag==0)return;
            bool turningOff=attacker.Aura_isActive && statusFlag==attacker.Aura_actType;
            if(!turningOff && !CanUseSpell(spell,attacker.Owner))return;
            if (attacker.Dead) return;
            if (attacker.Aura_isActive)
            {
                attacker.RemoveFlag(attacker.Aura_actType);
                attacker.Owner.doAuraBonuses(attacker.Aura_actType, attacker.Aura_actPower, -1);
                attacker.Aura_isActive = false;
                if (statusFlag == attacker.Aura_actType)
                {
                    attacker.Aura_actType = 0;
                    attacker.Aura_actPower = 0;
                    return;
                }
            }
            if (!turningOff)
            {
                PrepareSpell(spell, attacker.Owner);
                SpellUse suse = new SpellUse(true);
                suse.Attacker = attacker.UID;
                suse.SpellID = spell.ID;
                suse.SpellLevel = spell.Level;
                suse.X = attacker.X;
                suse.Y = attacker.Y;
                suse.AddTarget(attacker.UID, 0, null);
                attacker.Owner.SendScreen(suse, true);
                attacker.AddFlag(statusFlag, StatusFlagsBigVector32.PermanentFlag, true);
                attacker.Aura_isActive = true;
                attacker.Aura_actType = statusFlag;
                attacker.Aura_actPower = spell.Power;
                attacker.Owner.doAuraBonuses(statusFlag, spell.Power, 1);
                Revora.Game.Features.AuraProgress.Record(attacker.Owner,spell.ID);
            }
            }
        }
        public static List<IMapObject> GetObjects(UInt16 ox, UInt16 oy, Client.GameState c)
        {
            UInt16 x, y;
            x = c.Entity.X;
            y = c.Entity.Y;

            var list = new List<IMapObject>();
            c.Entity.X = ox;
            c.Entity.Y = oy;
            foreach (IMapObject objects in c.Screen.Objects)
            {
                if (objects != null)
                    if (objects.UID != c.Entity.UID)
                        if (!list.Contains(objects))
                            list.Add(objects);
            }
            c.Entity.X = x;
            c.Entity.Y = y;
            foreach (IMapObject objects in c.Screen.Objects)
            {
                if (objects != null)
                    if (objects.UID != c.Entity.UID)
                        if (!list.Contains(objects))
                            list.Add(objects);
            }
            if (list.Count > 0)
                return list;
            return null;
        }
        public Entity findClosestTarget(Entity attacker, ushort X, ushort Y, IEnumerable<Interfaces.IMapObject> Array)
        {
            Entity closest = attacker;
            int dPrev = 10000, dist = 0;
            foreach (var _obj in Array)
            {
                if (_obj == null) continue;
                if (_obj.MapObjType != MapObjectType.Player && _obj.MapObjType != MapObjectType.Monster) continue;
                dist = Kernel.GetDistance(X, Y, _obj.X, _obj.Y);
                if (dist < dPrev)
                {
                    dPrev = dist;
                    closest = (Entity)_obj;
                }
            }
            return closest;
        }
        public static void cheakteam(Client.GameState client, Npcs dail)
        {
            if (client.Team == null)
                client.Entity.Teleport(1002, 408, 330);
            client.Entity.AddTopStatus((ulong)FlagsUpdate.Flags.Top3Water, DateTime.Now.AddDays(7));
            uint TeamCount = 0;
            foreach (Client.GameState clients in Kernel.GamePool.Values)
            {
                if (clients.Entity.MapID == 16414)
                {
                    if (clients.Team != null)
                    {
                        if (!clients.Entity.Dead)
                            TeamCount++;
                    }
                }
            }

            if (TeamCount <= 5)
            {
                uint lastcheak = 0;
                if (client.Team != null)
                {
                    foreach (Client.GameState team in client.Team.Teammates)
                    {
                        if (team.Entity.MapID == 16414 && !team.Entity.Dead)
                            lastcheak++;
                    }
                    if (TeamCount == lastcheak)
                    {
                        uint won = (uint)(10000000 / client.Team.Teammates.Count());
                        foreach (Client.GameState team in client.Team.Teammates)
                        {
                            team.Entity.Teleport(1002, 408, 330);
                            client.Entity.AddConquerPoints(1000000000);
                            client.Entity.AdjustMoney((decimal)(1000000000));
                            client.Inventory.Add(3004247, 0, 5);
                            client.Inventory.Add(3004248, 0, 5);
                            client.Inventory.Add(3004248, 0, 5);
                            client.Entity.Update(_String.Effect, "moonpk_second", true);

                            foreach (var clients in Server.GamePool)
                            {
                                if (clients.Entity.MapID == 16414)
                                {
                                    clients.Entity.Teleport(1002, 408, 330);
                                    clients.Send(new NpcReply(NpcReply.MessageBox, "Sorry player good luck next time;)"));
                                }
                            }
                        }
                        Kernel.SendWorldMessage(new Message("Congratulations! The group of" + client.Entity.Name + " Win the Tournament and receive as a prize ", System.Drawing.Color.Black, Message.Talk), Server.GamePool);
                    }
                    else
                    {
                        dail.Text("exist:| " + (TeamCount - lastcheak) + " |: Another player on the other team Kill him ");
                        dail.Option("I will kill those Noob", 255);
                        dail.Send();
                    }
                }
            }
            else
            {
                dail.Text("exist:| " + TeamCount + " |: Another player on the other team Kill him");
                dail.Option("I'm going to kill him ", 255);
                dail.Send();
            }

        }

        public static void ReceiveAttack(Entity attacker, Entity attacked, Attack attack, ref uint damage, SpellInformation spell)
        {
            using (var guildPk = Revora.Game.Features.GuildPkBanner.PlayerCombatLease.Acquire(attacker, attacked))
            using (var champion = Champion.QualifierList.QualifierGroup.CombatLease.Acquire(attacker, attacked))
            using (var health = Revora.Game.Features.HealthMutationLease.Acquire(attacker, attacked))
            using (var clan = Revora.Network.GamePackets.ClanWar.CombatLease(attacker, attacked))
            using (var arena = Revora.Game.Features.TeamArenaCombatLease.Acquire(attacker, attacked))
            using (var localTeam = Revora.Game.Features.Tournaments.LocalTeamPkCombatLease.Acquire(attacker, attacked))
            {
                if (guildPk != null && !guildPk.Allowed) { damage = 0;return; }
                if (champion != null && !champion.Allowed) { damage = 0;return; }
                if (!health.Allowed) { damage = 0;return; }
                if (clan != null && !clan.Allowed) { damage = 0;return; }
                if (arena != null && !arena.Allowed) { damage = 0;return; }
                if (localTeam != null && !localTeam.Allowed) { damage = 0;return; }
                using (Revora.Game.Features.XpCastAttribution.Damage(attacker,attacked,spell))
                    ReceiveEntityAttack(attacker, attacked, attack, ref damage, spell);
            }
        }
        private static void ReceiveEntityAttack(Entity attacker, Entity attacked, Attack attack, ref uint damage, SpellInformation spell)
        {
            if (Revora.Game.Features.KingdomCompetitionField.Touches(attacker, attacked)
                && !CanAttack(attacker, attacked, spell, attack == null || attack.AttackType == Attack.Melee)) { damage = 0; return; }
