            using (Revora.Game.Features.HeartEncounter.DamageLease(attacker, attacked))
            using (Revora.Game.Features.PlanetEncounter.DamageLease(attacker, attacked))
            using (Revora.Game.Features.EliminationRescueWorld.DamageLease(attacker, attacked))
            using (Revora.Game.Features.EliminationDenWorld.DamageLease(attacker, attacked))
            using (Revora.Game.Features.AncientDevilBossWorld.DamageLease(attacker, attacked))
            using (Revora.Game.Features.AncientDevilWorld.DamageLease(attacker, attacked))
            using (Revora.Game.Features.WarriorEpicCombat.DamageLease(attacker, attacked))
