                                FlagsUpdate upgrade = new FlagsUpdate(true);
                                upgrade.UID = attacker.UID;
                                upgrade.Append(104, 0, 0, 0, 0);
                                attacker.Owner.Send(upgrade.ToArray());
                            }
                        }
                    }
