                    if (spell != null && !spell.IsMagic && damage < 22000)
                    {
                        if (attacker.Owner.Spells.ContainsKey((ushort)Enums.Skill.NoMercy))
                        {
                            damage += (uint)attacker.NoMercyDamage;
                            if (damage > 22000)
                                damage = 22000;
                        }
                    }
                    #endregion
                    #region Witchery
                    if (spell != null && spell.IsMagic && damage < 15000)
                    {
                        if (attacker.Owner.Spells.ContainsKey((ushort)Enums.Skill.Witchery))
                        {
                            damage += (uint)attacker.WitcheryDamage;
                            if (damage > 15000)
                                damage = 15000;
                        }
                    }
