                        {
                            var DBSpell = SpellTable.GetSpell(ClientSpell.ID, ClientSpell.Level);
                            if (attacked.ContainsFlag((ulong)FlagsUpdate.Flags.Fly) || attacked.ContainsFlag((ulong)FlagsUpdate.Flags.Infinity) ||
                                attacked.ContainsFlag((ulong)FlagsUpdate.Flags.DefensiveStance) || attacked.ContainsFlag((ulong)FlagsUpdate.Flags.ManiacDance) ||
                                attacked.ContainsFlag((ulong)FlagsUpdate.Flags.ShurikenVortex))
                            {
                                damage += (uint)DBSpell.Damage1;
                                attack.Effect |= Attack.AttackEffects.BurningSky;
                            }
                        }
                    }
                    #endregion
                }
            }
