            if (attacker.EntityFlag == EntityFlag.Player && attacked.EntityFlag == EntityFlag.Player)
            {
                if (attacked != null && attacked.MapID == Sistemas.Quarantine.Map)
                {
                    damage = Sistemas.Quarantine.HandleQuarantine(attacker, attacked, spell) ? 1u : 0u;
                }
            }
            #endregion
            if (attacked.EntityFlag == EntityFlag.Player)
                if (!(attacked.Name.Contains("Guard") && attacked.EntityFlag == EntityFlag.Monster))
                {
                    if (attacker.EntityFlag == EntityFlag.Player && attacked.EntityFlag != EntityFlag.Player && !attacked.Name.Contains("Guard"))
                    {
                        if (damage > attacked.Hitpoints)
                        {
                            attacker.Owner.IncreaseExperience(Calculate.CalculateExpBonus(attacker.Level, attacked.Level, Math.Min(damage, attacked.Hitpoints)), true);
                            if (spell != null) attacker.Owner.IncreaseSpellExperience((uint)Calculate.CalculateExpBonus(attacker.Level, attacked.Level, Math.Min(damage, attacked.Hitpoints)), spell.ID);
                        }
                        else
                        {
                            attacker.Owner.IncreaseExperience(Calculate.CalculateExpBonus(attacker.Level, attacked.Level, damage), true);
                            if (spell != null) attacker.Owner.IncreaseSpellExperience((uint)Calculate.CalculateExpBonus(attacker.Level, attacked.Level, damage), spell.ID);
                        }
                    }
                }
            if (attacker.EntityFlag == EntityFlag.Monster && attacked.EntityFlag == EntityFlag.Player)
            {
                if (attacked.Action == Enums.ConquerAction.Sit)
                    if (attacked.Stamina > 20)
                        attacked.Stamina -= 20;
                    else attacked.Stamina = 0;
                attacked.Action = Enums.ConquerAction.None;
            }

            if (attack.AttackType == Attack.Magic)
            {
                #region Maximum kills
                if (attacker.MapID == 19987)
                {
                    attacker.MaximasMuertesRecord++;
                    string[] scoreMessages = new string[50];
                    scoreMessages[0] = attacker.Name + " : " + attacker.MaximasMuertesRecord;
                    int count = 0;
                    Message msg = new Message(scoreMessages[count], System.Drawing.Color.Red, count == 1 ? Message.FirstRightCorner : Message.ContinueRightCorner);
                    Kernel.SendWorldMessage(msg, Server.GamePool);
                    foreach (var client in Server.GamePool)
                    {
                        if (client.Map.ID == attacker.MapID)
                        {
                            count++;
                            scoreMessages[count] = client.Entity.Name + " :[Kills]: " + client.Entity.MaximasMuertesRecord;
                            Message msg1 = new Message(scoreMessages[count], System.Drawing.Color.Red, count == 1 ? Message.FirstRightCorner : Message.ContinueRightCorner);
                            Kernel.SendWorldMessage(msg1, Server.GamePool);

                        }
                    }

                }
                #endregion

                if (attacked.Hitpoints <= damage && Revora.Game.Features.GuildPkBanner.InBattle(attacked)) {
                    attacked.Die(attacker);attacker.AttackPacket=null;return;
                }
                if (attacked.Hitpoints <= damage)
                {
                    Revora.Game.Features.Tournaments.LocalTeamPkCombat.Damage(attacker, attacked, attacked.Hitpoints);
                    Revora.Game.Features.ElitePkEvent.Damage(attacker, attacked, attacked.Hitpoints);
                    Revora.Game.Features.LocalPkWar.Damage(attacker, attacked, attacked.Hitpoints);
                    Revora.Game.Features.CouplePkEvent.Damage(attacker, attacked, attacked.Hitpoints);
                    attacker.Owner.UpdateQualifier(attacker.Owner, attacked.Owner, attacked.Hitpoints);
                    attacked.CauseOfDeathIsMagic = true;
                    attacked.Die(attacker);
                    Revora.Game.Features.Tournaments.LocalTeamPkCombat.Death(attacker, attacked);

                    attacked.IsDropped = false;

                    if (attacker.PKMode == Enums.PKMode.Jiang)
                    {
                        if (attacked.JiangActive)
                        {
                            if (attacker.MyJiang != null && attacked.MyJiang != null)
                            {
                                attacker.MyJiang.GetKill(attacker.Owner, attacked.MyJiang);
                            }
                        }
