        public static void ReceiveAttack(Game.Entity attacker, SobNpcSpawn attacked, Attack attack, uint damage, SpellInformation spell)
        {
            if (Revora.Game.Features.GuildPkBanner.Hit(attacker, attacked, attack, damage)) return;
            if (Revora.Game.Features.ElitePkEvent.InEvent(attacker)) return;
            if (Revora.Game.Features.LocalPkWar.InEvent(attacker)) return;
            if (Revora.Game.Features.CouplePkEvent.InEvent(attacker)) return;
            if (Revora.Game.Features.GuildSeasonWar.Hit(attacker, attacked, attack, damage, spell)) return;
            #region Pole domination
            if (attacked.UID == 12345)
            {
                if (Server.Thread.PoleDomination.KillerGuildID == attacker.Owner.Guild.ID)
                    return;
                Server.Thread.PoleDomination.AddScore(damage, attacker.Owner.Guild);
            }
            #endregion
            #region Elite Guild War
            if (Game.EliteGuildWar.HitPole(attacker, attacked, attack, damage)) return;
            #endregion
            #region Crow
            if (attacker.EntityFlag == EntityFlag.Player)
                if (damage > attacked.Hitpoints)
                {
                    if (attacker.MapID == 1039)
                        attacker.Owner.IncreaseExperience(Math.Min(damage, attacked.Hitpoints), true);
                    if (spell != null)
                        attacker.Owner.IncreaseSpellExperience(Math.Min(damage, attacked.Hitpoints), spell.ID);
                }
                else
                {
                    if (attacker.MapID == 1039)
                        attacker.Owner.IncreaseExperience(damage, true);
                    if (spell != null)
                        attacker.Owner.IncreaseSpellExperience(damage, spell.ID);
                }
            #endregion
            #region PoleEmulator
            if (attacked.UID == 123456)
            {
                if (Server.Thread.PoleEmulator.KillerGuildID == attacker.Owner.Guild.ID)
                    return;
                Server.Thread.PoleEmulator.AddScore(damage, attacker.Owner.Guild);
            }
            #endregion
            #region GuildWar
            if (Game.GuildWar.IsWar)
            {
                if (attacker.MapID == 1038)
                {
                    if (attacked.UID == 810)
                    {
                        if (Game.GuildWar.PoleKeeper == attacker.Owner.Guild) return;
                        if (attacked.Hitpoints <= damage) attacked.Hitpoints = 0;
                        Game.GuildWar.AddScore(damage, attacker.Owner.Guild);
                    }
                }
            }
            #endregion
            #region PoleDragon
            if (attacker.MapID == 2072)
            {
                if (attacked.UID == 819)
                {
                    if (Game.PoleTwin.PoleKeeper3 == attacker.Owner.Guild)
                        return;
                    if (attacked.Hitpoints <= damage)
                        attacked.Hitpoints = 0;
                    Game.PoleTwin.AddScore(damage, attacker.Owner.Guild);
                }
            }
            #endregion
            #region SuperGuildWar
            if (Game.SuperGuildWar.HitPole(attacker, attacked, attack, damage)) return;
            #endregion
            #region CaptureTheFlag
            if (attacker.MapID == CaptureTheFlag.MapID)
            {
                Server.Thread.CTF.HitBase(attacker.Owner, attacked, damage);
                return;
            }
            #endregion
            #region Hitpoints
            if (attack.AttackType == Attack.Magic)
            {
                if (attacked.Hitpoints <= damage)
                {
                    attacked.Die(attacker);

                }
                else
                {
                    attacked.Hitpoints -= damage;
                }
            }
            else
            {
                attacker.Owner.SendScreen(attack, true);
                if (attacked.Hitpoints <= damage)
                {
                    attacked.Die(attacker);
                }
                else
                {
                    attacked.Hitpoints -= damage;
                    attacker.AttackPacket = attack;
                    attacker.AttackStamp = Time32.Now;
                }
            }
            #endregion
            #region pole nobility
            if (NobiltyPoleWar.IsWar)
            {
                if (attacker.MapID == NobiltyPoleWar.Map.ID)
                {
                    NobiltyPoleWar.Attack(damage, attacker, attacked);
                }
            }
            #endregion

        }
        public static bool CanUseSpell(Database.SpellInformation spell, Client.GameState client)
        {
            if (spell != null && client != null && client.ChampionGroup != null && SkillTable.DerivedRuneSkill(spell.ID)) return false;
            if (spell != null && !Revora.Game.Features.TrojanEpicTraining.CanPerform(client, spell.ID)) return false;
            if (Revora.Game.Features.ElitePkEvent.BlockSpell(client)) return false;
            if (Revora.Game.Features.LocalPkWar.BlockSpell(client)) return false;
            if (Revora.Game.Features.CouplePkEvent.BlockSpell(client)) return false;
            if (spell != null && client != null && Revora.Game.Features.WaveDefenseSystem.BlocksHealSpell(client, spell.ID))
            {
                client.Send(new Message("The Warden Medic is the only heal here. Wait for the pulse.", System.Drawing.Color.Red, Message.TopLeft));
                return false;
            }
            #region ColdDown
            ISkill ClientSpell;
            if (client.Entity.MapID != 1039)
            {
                if (client.Spells.TryGetValue(spell.ID, out ClientSpell))
                {
                    if (!(client.Entity.EpicMonje() && spell.ID == 10425))
                    {
                        Time32 now = Time32.Now;
                        if (spell.IsColdTime)
                        {
                            if (ClientSpell.ColdTime > now)
                                return false;
                            else
                            {
                                ClientSpell.IsSpellWithColdTime = true;
                                ClientSpell.ColdTime = now.AddMilliseconds(spell.ColdTime);
                            }
                        }
                    }
                }
            }
            #endregion
            #region CP wager
            if (Constants.ZonaTroyanos.Contains(client.Entity.MapID))
            {
                if (spell.ID != 1045 && spell.ID != 1046)
                {
                    client.Send(new Message("You can only use FB & SS.", System.Drawing.Color.Red, 0x7dc));
                    return false;
                }
            }
            if (Constants.ZonaNinjas.Contains(client.Entity.MapID))
            {
                if (spell.ID != 12080)
                {
                    client.Send(new Message("You can only use Super Double Katanaso.", System.Drawing.Color.Red, 0x7dc));
                    return false;
                }
            }
            if (Constants.ZonaMonjes.Contains(client.Entity.MapID))
            {
                if (spell.ID != 10381)
                {
                    client.Send(new Message("You can only use Palma.", System.Drawing.Color.Red, 0x7dc));
                    return false;
                }
            }
            #endregion
            #region Quarantine
            if (client.Entity.MapID == Sistemas.Quarantine.Map)
                if (spell != null)
                    if (!Sistemas.Quarantine.AllowedSpells.Contains(spell.ID))
                    {
                        client.Send(new Message("Just FastBlade, ScentSword, ViperFang, DragonSlash or RageofWar is allowed here.", Color.Red, Message.TopLeft));
                        return false;
                    }
            #endregion
            if (client.Entity.SkillTeamWatchingElitePKMatch != null)
                return false;
            if (client.WatchingElitePKMatch != null)
                return false;
            if (client.WatchingGroup != null)
                return false;
            if (client.TeamWatchingGroup != null)
                return false;
            if (spell == null)
                return false;
            uint Mana = spell.UseMana;
            if (client.Entity.MPMaster > 0)
            {
                Mana = (spell.UseMana * client.Entity.MPMaster / 100);
                Mana = (spell.UseMana - Mana);
            }
            if (client.Entity.Mana < Mana)
                return false;
            if (client.Entity.Stamina < spell.UseStamina)
                return false;
            //if (client.Player.MapID == 1707)
            //{
            //    if (spell.ID != 1045 && spell.ID != 1046)
            //    {
            //        client.Send(new Message("You can't use any skills here Except FB And SS!", System.Drawing.Color.Red, 0x7dc));
            //        return false;
            //    }
            //}
            if (spell.UseArrows > 0 && isArcherSkill(spell.ID))
            {
                var weapons = client.Weapons;
                if (weapons.Item2 != null)
                    if (!client.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.PathOfShadow))
                        if (!ItemHandler.IsArrow(weapons.Item2.ID))
                            return false;
                return true;
            }
            if (spell.NeedXP == 1 && !client.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.XPList))
                return false;
            return true;
        }
        public static void PrepareSpell(SpellInformation spell, Client.GameState client)
        {
            Revora.Game.Features.XpCastAttribution.Prepared(spell,client);
            Revora.Game.Features.ArenaBotBrain.Prepared(client,spell.ID);
            if (spell.NeedXP == 1)
                client.Entity.RemoveFlag((ulong)FlagsUpdate.Flags.XPList);
            if (client.Map.ID != 1039)
            {
                if (spell.UseMana > 0)
                {
                    uint Mana = spell.UseMana;
                    if (client.Entity.MPMaster > 0)
                    {
                        Mana = (spell.UseMana * client.Entity.MPMaster / 100);
                        Mana = (spell.UseMana - Mana);
                    }
                    if (client.Entity.Mana >= Mana)
                        client.Entity.Mana -= (ushort)Mana;
                }
                if (spell.UseStamina > 0)
                    if (client.Entity.Stamina >= spell.UseStamina)
                        client.Entity.Stamina -= spell.UseStamina;
                #region Rampage
                if (client.Spells.ContainsKey(14190))
                {
                    var ss = client.Entity.Owner.Spells[14190];
                    var habilidad = SpellTable.SpellInformations[ss.ID][ss.Level];
                    if (habilidad != null && client.Spells.ContainsKey(14190))
                        if (client.Entity.Class / 10 == 1)
                            if (client.Entity.Stamina <= 10)
                                RunesSystem.HandleRedBlueRunesSkills(null, client.Entity, null, habilidad, client.Entity.X, client.Entity.Y);
                }
                #endregion
            }
        }
        private static void HitWorldActor(Entity attacker, Entity attacked)
        {
            if (attacker == null || attacked == null || attacked.Dead) return;
            Attack blow = new Attack(true);
            blow.Effect = Attack.AttackEffects.None;
            uint damage = 1;
            try
            {
                damage = Calculate.Melee(attacker, attacked, ref blow);
            }
            catch
            {
                damage = (uint)Math.Max(1, attacker.MinAttack);
            }
            if (damage < 1) damage = 1;
            blow.Attacker = attacker.UID;
            blow.Attacked = attacked.UID;
            blow.AttackType = Attack.Melee;
            blow.Damage = damage;
            blow.X = attacked.X;
            blow.Y = attacked.Y;
            if (attacked.Hitpoints <= damage)
            {
                Kernel.SendScreen(attacker, blow);
                attacked.Die(attacker);
            }
            else
            {
                attacked.Hitpoints -= damage;
                Kernel.SendScreen(attacker, blow);
            }
        }

        public static bool CanAttack(Entity attacker, SobNpcSpawn attacked, SpellInformation spell)
        {
            if (Revora.Game.Features.GuildPkBanner.Managed(attacker, attacked)) return Revora.Game.Features.GuildPkBanner.CanAttack(attacker, attacked);
            if (attacker != null && attacker.Owner != null && attacker.Owner.ChampionGroup != null) return false;
            if (Revora.Game.Features.ElitePkEvent.InEvent(attacker)) return false;
            if (Revora.Game.Features.LocalPkWar.InEvent(attacker)) return false;
            if (Revora.Game.Features.CouplePkEvent.InEvent(attacker)) return false;
            if (Revora.Game.Features.GuildSeasonWar.Managed(attacked)) return Revora.Game.Features.GuildSeasonWar.CanAttack(attacker, attacked);

            #region Pole domination
            if (attacked.UID == 12345)
                if (attacked.Hitpoints > 0)
                    if (attacker.GuildID != 0 && attacker.GuildID != Server.Thread.PoleDomination.KillerGuildID)
                        return true;
                    else return false;
                else return false;
            #endregion
            #region Elite Guild War
            if (attacker.MapID == 2071)
            {
                if (attacker.GuildID == 0 || !Game.EliteGuildWar.IsWar)
                {
                    if (attacked.UID == 88816)
                    {
                        return false;
                    }
                }
                if (Game.EliteGuildWar.PoleKeeper != null)
                {
                    if (Game.EliteGuildWar.PoleKeeper == attacker.Owner.Guild)
                    {
