                    attacker.AttackPacket = null;
                    return false;
                }
                else
                {
                    if (!attacked.ContainsFlag((ulong)FlagsUpdate.Flags.FlashingName))
                    {
                        if (!attacked.ContainsFlag((ulong)FlagsUpdate.Flags.BlackName))
                        {
                            if (Constants.PKFreeMaps.Contains(attacker.MapID)) return true;
                            if (Revora.Game.Features.AbyssTrialWorld.SuppressCrime(attacker,attacked)) return true;
                            if (attacker.Owner.Map.BaseID == 700) return true;
                            attacker.AddFlag((ulong)Network.GamePackets.FlagsUpdate.Flags.FlashingName, 20, true);
                        }
                    }
                    return true;
                }
            }
        }
        public static void RageOfWarTrap(FloorItem item)
        {
            var attack = new Attack(true);
            var spell = Database.SpellTable.GetSpell(12930, item.Owner);
            var suse = new SpellUse(true);
            attack.Attacker = suse.Attacker = item.Owner.Entity.UID;
            attack.SpellID = suse.SpellID = spell.ID;
            suse.X = item.X;
            suse.Y = item.Y;
            suse.SpellLevel = spell.Level;
            suse.SpellEffect = 1;
            Sector sector = new Sector(item.X, item.Y, item.X, item.Y);
            sector.Arrange(spell.Sector, 3);
            Entity attacked = null;
            foreach (Interfaces.IMapObject _obj in item.Owner.Screen.Objects)
            {
                if (_obj == null) continue;
                if (_obj.MapObjType == MapObjectType.Monster)
                {
                    attacked = _obj as Entity;
                    if (sector.Inside(attacked.X, attacked.Y))
                    {
                        if (CanAttack(item.Owner.Entity, attacked, spell, attack.AttackType == Attack.Melee))
                        {
                            attack.Effect = Attack.AttackEffects.None;
                            uint damage = Game.Attacking.Calculate.Melee(item.Owner.Entity, attacked, ref attack);

                            attack.Damage = damage / 2;
                            suse.Effect = attack.Effect;
                            ReceiveAttack(item.Owner.Entity, attacked, attack, ref damage, spell);
                            suse.AddTarget(attacked.UID, damage, attack);
                        }
                    }

                }
                if (_obj.MapObjType == MapObjectType.Player)
                {
                    attacked = _obj as Entity;
                    if (sector.Inside(attacked.X, attacked.Y))
                    {
                        if (CanAttack(item.Owner.Entity, attacked, spell, attack.AttackType == Attack.Melee))
                        {
                            attack.Effect = Attack.AttackEffects.None;
                            uint damage = Game.Attacking.Calculate.Melee(item.Owner.Entity, attacked, ref attack);
                            // Pezzi, the best of all by far
                            attack.Damage = damage / 2;
                            suse.Effect = attack.Effect;
                            ReceiveAttack(item.Owner.Entity, attacked, attack, ref damage, spell);
                            suse.AddTarget(attacked.UID, damage, attack);
                        }
                    }

                }
            }
            item.Owner.SendScreen(suse, true);
        }
        public static void CheckForExtraWeaponPowers(Client.GameState client, Entity attacked)
        {
            #region Right Hand
            var weapons = client.Weapons;
            if (weapons.Item1 != null)
            {
                if (weapons.Item1.ID != 0)
                {
                    var Item = weapons.Item1;
                    if (Item.Effect != Enums.ItemEffect.None)
                    {
                        if (Kernel.Rate(30))
                        {
                            switch (Item.Effect)
                            {
                                case Enums.ItemEffect.HP:
                                    {
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1175;
                                        spellUse.SpellLevel = 4;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 300, null);
                                        Revora.Game.Features.HealthMutationLease.Heal(client.Entity,300);
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.MP:
                                    {
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1175;
                                        spellUse.SpellLevel = 2;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 300, null);
                                        ushort damage = (ushort)Math.Min(300, client.Entity.MaxMana - client.Entity.Mana);
                                        client.Entity.Mana += damage;
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.Shield:
                                    {
                                        if (client.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.MagicShield)) return;
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1020;
                                        spellUse.SpellLevel = 0;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 120, null);
                                        client.Entity.ShieldTime = 0;
                                        client.Entity.ShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldTime = 0;
                                        client.Entity.AddFlag((ulong)FlagsUpdate.Flags.MagicShield, 120, true);
                                        client.Entity.MagicShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldIncrease = 2;
                                        client.Entity.MagicShieldTime = 120;
                                        if (client.Entity.EntityFlag == EntityFlag.Player)
                                            client.Send(Constants.Shield(2, 120));
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.Poison:
                                    {
                                        if (attacked != null)
                                        {
                                            if (Constants.PKForbiddenMaps.Contains(client.Entity.MapID)) return;
                                            if (client.Map.BaseID == 700) return;
                                            if (attacked.UID == client.Entity.UID) return;
                                            if (attacked.ToxicFogLeft > 0) return;
                                            SpellUse spellUse = new SpellUse(true);
                                            spellUse.SpellID = 5040;
                                            spellUse.Attacker = attacked.UID;
                                            spellUse.SpellLevel = 9;
                                            spellUse.X = attacked.X;
                                            spellUse.Y = attacked.Y;
                                            spellUse.AddTarget(attacked.UID, 0, null);
                                            spellUse.Targets[attacked.UID].Hit = true;
                                            attacked.ToxicFogStamp = Time32.Now;
                                            attacked.ToxicFogLeft = 10;
                                            attacked.ToxicFogPercent = 0.05F;
                                            client.SendScreen(spellUse, true);
                                        }
                                        break;
                                    }
                            }
                        }
                    }
                }
            }
            #endregion
            #region Left Hand
            if (weapons.Item2 != null)
            {
                if (weapons.Item2.ID != 0)
                {
                    var Item = weapons.Item2;
                    if (Item.Effect != Enums.ItemEffect.None)
                    {
                        if (Kernel.Rate(30))
                        {
                            switch (Item.Effect)
                            {
                                case Enums.ItemEffect.HP:
                                    {
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1175;
                                        spellUse.SpellLevel = 4;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 300, null);
                                        Revora.Game.Features.HealthMutationLease.Heal(client.Entity,300);
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.MP:
                                    {
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1175;
                                        spellUse.SpellLevel = 2;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 300, null);
                                        ushort damage = (ushort)Math.Min(300, client.Entity.MaxMana - client.Entity.Mana);
                                        client.Entity.Mana += damage;
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.Shield:
                                    {
                                        if (client.Entity.ContainsFlag((ulong)FlagsUpdate.Flags.MagicShield))
                                            return;
                                        SpellUse spellUse = new SpellUse(true);
                                        spellUse.Attacker = 1;
                                        spellUse.SpellID = 1020;
                                        spellUse.SpellLevel = 0;
                                        spellUse.X = client.Entity.X;
                                        spellUse.Y = client.Entity.Y;
                                        spellUse.AddTarget(client.Entity.UID, 120, null);
                                        client.Entity.ShieldTime = 0;
                                        client.Entity.ShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldTime = 0;

                                        client.Entity.AddFlag((ulong)FlagsUpdate.Flags.MagicShield, 120, true);
                                        client.Entity.MagicShieldStamp = Time32.Now;
                                        client.Entity.MagicShieldIncrease = 2;
                                        client.Entity.MagicShieldTime = 120;
                                        if (client.Entity.EntityFlag == EntityFlag.Player)
                                            client.Send(Constants.Shield(2, 120));
                                        client.SendScreen(spellUse, true);
                                        break;
                                    }
                                case Enums.ItemEffect.Poison:
                                    {
                                        if (attacked != null)
                                        {
                                            if (attacked.UID == client.Entity.UID) return;
                                            if (Constants.PKForbiddenMaps.Contains(client.Entity.MapID)) return;
                                            if (client.Map.BaseID == 700) return;
                                            if (attacked.ToxicFogLeft > 0) return;
                                            SpellUse spellUse = new SpellUse(true);
                                            spellUse.SpellID = 5040;
                                            spellUse.Attacker = attacked.UID;
                                            spellUse.SpellLevel = 9;
                                            spellUse.X = attacked.X;
                                            spellUse.Y = attacked.Y;
                                            spellUse.AddTarget(attacked.UID, 0, null);
                                            spellUse.Targets[attacked.UID].Hit = true;
                                            attacked.ToxicFogStamp = Time32.Now;
                                            attacked.ToxicFogLeft = 10;
                                            attacked.ToxicFogPercent = 0.05F;
                                            client.SendScreen(spellUse, true);
                                        }
                                        break;
                                    }
                            }
                        }
                    }
                }
            }
            #endregion
        }
    }
